def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 1})
    for color in colors:
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        crop = [row[c0:c1+1] for row in grid[r0:r1+1]]
        crop = [[1]*(len(crop[0])+2)] + [[1]+row+[1] for row in crop] + [[1]*(len(crop[0])+2)]
        ch, cw = len(crop), len(crop[0])
        exterior = set()
        q = deque()
        for r in range(ch):
            for c in range(cw):
                if crop[r][c] == 1 and (r in (0,ch-1) or c in (0,cw-1)):
                    exterior.add((r,c)); q.append((r,c))
        while q:
            r,c = q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc = r+dr,c+dc
                if 0 <= nr < ch and 0 <= nc < cw and crop[nr][nc] == 1 and (nr,nc) not in exterior:
                    exterior.add((nr,nc)); q.append((nr,nc))
        holes = [(r,c) for r in range(ch) for c in range(cw) if crop[r][c] == 1 and (r,c) not in exterior]
        if holes:
            fill = next(v for v in colors if v != color and all(grid[r][c] != v for r in range(r0,r1+1) for c in range(c0,c1+1)))
            # The separate smallest object supplies the fill color.
            sizes = {v: sum(row.count(v) for row in grid) for v in colors if v != color}
            fill = min(sizes, key=sizes.get)
            crop = [row[1:-1] for row in crop[1:-1]]
            return [[fill if (r+1,c+1) in holes else v for c,v in enumerate(row)] for r,row in enumerate(crop)]
    return grid

