code='''def transform(grid):
    from collections import Counter, deque
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    def components(cells):
        cells=set(cells); out=[]
        while cells:
            seed=cells.pop(); comp={seed}; q=deque([seed])
            while q:
                r,c=q.popleft()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(r+dr,c+dc)
                    if p in cells: cells.remove(p); comp.add(p); q.append(p)
            out.append(comp)
        return out
    objects=[]
    for color in sorted({v for row in grid for v in row if v!=bg}):
        for comp in components((r,c) for r in range(h) for c in range(w) if grid[r][c]==color): objects.append((color,comp))
    pieces=[o for o in objects if len(o[1])<=9]
    best=None
    for color,cells in objects:
        if len(cells)<=9: continue
        r0,r1=min(r for r,c in cells),max(r for r,c in cells); c0,c1=min(c for r,c in cells),max(c for r,c in cells)
        crop=[row[c0:c1+1] for row in grid[r0:r1+1]]; ch,cw=len(crop),len(crop[0])
        placements=[]
        for col,comp in pieces:
            pr0,pr1=min(r for r,c in comp),max(r for r,c in comp); pc0,pc1=min(c for r,c in comp),max(c for r,c in comp)
            shape={(r-pr0,c-pc0) for r,c in comp}
            opts=[]
            for dr in range(ch-pr1+pr0):
                for dc in range(cw-pc1+pc0):
                    placed={(r+dr,c+dc) for r,c in shape}
                    if all(crop[r][c]==bg for r,c in placed): opts.append(placed)
            placements.append((col,opts))
        def search(i,used,filled,chosen):
            nonlocal bestpack
            score=sum(map(len,chosen))
            if score>bestpack[0]: bestpack=(score,chosen[:])
            for j in range(i,len(placements)):
                col,opts=placements[j]
                for p in opts:
                    if not p&used: search(j+1,used|p,filled|p,chosen+[(col,p)])
        bestpack=(0,[])
        search(0,set(),set(),[])
        if best is None or bestpack[0]>best[0]: best=(bestpack[0],crop,bestpack[1])
    _,crop,packing=best
    for col,cells in packing:
        for r,c in cells: crop[r][c]=col
    return crop
